package com.dy.artisan3d.ui.screen.products.viewimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.repository.ProductDetailRepositoryimport com.dy.artisan3d.util.toErrorMessageimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass ProductDetailViewModel(    private val repository: ProductDetailRepository,    private val appLang: AppLanguage,    private val productId: Int,) : ViewModel() {    private val _uiState = MutableStateFlow<ProductDetailUiState>(ProductDetailUiState())    val uiState: StateFlow<ProductDetailUiState> = _uiState.asStateFlow()    private val _selectedImageIndex = MutableStateFlow(0)    val selectedImageIndex: StateFlow<Int> = _selectedImageIndex.asStateFlow()    private val _show3DModel = MutableStateFlow(false)    val show3DModel: StateFlow<Boolean> = _show3DModel.asStateFlow()    init {        loadProductDetail()    }    fun loadProductDetail() {        viewModelScope.launch {            try {                _uiState.update { it.copy(isLoading = true) }                val response = repository.getProductDetail(productId, appLang.current)                _uiState.update {                    it.copy(                        product = response.getOrThrow(),                        isLoading = false,                        isError = false                    )                }            }catch (e: Exception){                val errorMsg = if (e is NetworkError) {                    e.toErrorMessage()                } else {                    Res.string.error_unknown                }                _uiState.update {                    it.copy(                        isLoading = false,                        isError = true,                        error = errorMsg                    )                }            }        }    }    fun selectImage(index: Int) {        _selectedImageIndex.value = index    }    fun toggle3DModel() {        _show3DModel.value = !_show3DModel.value    }    fun show3DModel() {        _show3DModel.value = true    }    fun hide3DModel() {        _show3DModel.value = false    }}